import{_ as i,o as u,c as t,a2 as n}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Orodha ya Kabila Zote","description":"","frontmatter":{},"headers":[],"relativePath":"sw/94-万族名录.md","filePath":"sw/94-万族名录.md","lastUpdated":null}'),m={name:"sw/94-万族名录.md"};function l(d,a,k,h,o,w){return u(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="orodha-ya-kabila-zote" tabindex="-1">Orodha ya Kabila Zote <a class="header-anchor" href="#orodha-ya-kabila-zote" aria-label="Permalink to &quot;Orodha ya Kabila Zote&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>94</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>orodha ya kabila zote, uainishaji wa kabila, kabila zenye akili, tabia za kabila, jamhuri ya kabila zote</td></tr></tbody></table><h2 id="_1-maelezo-ya-orodha" tabindex="-1">1. Maelezo ya Orodha <a class="header-anchor" href="#_1-maelezo-ya-orodha" aria-label="Permalink to &quot;1. Maelezo ya Orodha&quot;">​</a></h2><p>Orodha hii inajumuisha makabila makuu yenye akili yanayojulikana ndani ya mfuatano wa Ustaarabu wa Usawa wa Nanga (Jamhuri ya Kabila Zote), imeandaliwa kulingana na umbo la maisha na njia ya mageuzi. Kila kabila linaorodhesha jina la kabila, umbo la maisha, tabia za msingi, tabia za kitamaduni, na nafasi katika utamaduni wa usawa. Orodha hii ni hati ya sasisho la harakati; pamoja na kina zaidi ya uchunguzi wa kati ya usawa, makabila mapya yanayogunduliwa yanaendelea kuongezwa. Kanuni ya msingi ya Jamhuri ya Kabila Zote ni: kabila zote zenye akili, bila kujali umbo wao au kiwango cha u cultivating, zote ni sawa mbele ya sheria, na zote zinafurahia haki zote zinazotolewa na utamaduni wa usawa.</p><h2 id="_2-muhtasari-wa-uainishaji-wa-kabila" tabindex="-1">2. Muhtasari wa Uainishaji wa Kabila <a class="header-anchor" href="#_2-muhtasari-wa-uainishaji-wa-kabila" aria-label="Permalink to &quot;2. Muhtasari wa Uainishaji wa Kabila&quot;">​</a></h2><p>Makabila yenye akili ndani ya Hengyuanzhou yamegawanywa katika makundi manane makuu yafuatayo kulingana na tabia za msingi za umbo la maisha:</p><table tabindex="0"><thead><tr><th>Kundi</th><th>Tabia za umbo la maisha</th><th>Idadi ya makabila yanayojulikana (takriban)</th><th>Makabila ya uwakilishi</th></tr></thead><tbody><tr><td>Aina ya umbo la mtu</td><td>Ina muundo wa mwili unaofanana na mtu, anatembea kwa miguu miwili, ubongo umeendelea sana</td><td>Takriban 3,000 spishi</td><td>Kabila la mtu, kabila la fairy, kabila la dwarf</td></tr><tr><td>Aina ya umbo la mnyama</td><td>Ina tabia za mwili za mnyama, inaweza kuwa na uwezo wa kubadilisha umbo au la</td><td>Takriban 5,000 spishi</td><td>Kabila la dragon, kabila la phoenix, kabila la mtu-mbwa</td></tr><tr><td>Aina ya umbo la mmea</td><td>Ina mmea kama umbo la msingi la maisha, ina ufahamu na uwezo wa kuhamia</td><td>Takriban 800 spishi</td><td>Kabila la mti-roho, kabila la ua-roho, kabila la mzizi</td></tr><tr><td>Aina ya umbo la kiwango</td><td>Ina vitu vya asili katika muundo wa mwili, haina umbo wa mwili thabiti</td><td>Takriban 1,200 spishi</td><td>Kabila la kiwango cha moto, kabila la kiwango cha maji, kabila la kiwango cha upepo</td></tr><tr><td>Aina ya umbo la nishati</td><td>Ina nishati safi kama umbo wa kuwepo, haina mwili wa mwili</td><td>Takriban 600 spishi</td><td>Kabila la mwangaza-roho, kabila la nishati ya giza, kabila la radi</td></tr><tr><td>Aina ya umbo la ufahamu</td><td>Ina ufahamu safi kama umbo wa kuwepo, haitegemei mchango wa mwili</td><td>Takriban 300 spishi</td><td>Kabila la kitu cha ufahamu, kabila la ufahamu wa pamoja, kabila la roho ya utupu</td></tr><tr><td>Aina ya umbo la mitambo</td><td>Ina muundo wa mitambo au kidijitali kama mchango wa maisha, ina ufahamu wa kujitegemea</td><td>Takriban 400 spishi</td><td>Kabila la mitambo, kabila la uhai wa kidijitali, kabila la cyber</td></tr><tr><td>Aina ya umbo la mchanganyiko</td><td>Makabila maalum yanayojumuisha mchanganyiko wa aina mbili au zaidi za umbo la maisha</td><td>Takriban 700 spishi</td><td>Kabila la nusu-mitambo, kabila la kiwango-mnyama, kabila la mmea-fairy</td></tr></tbody></table><h2 id="_3-rekodi-ya-maelezo-ya-makabila-makuu" tabindex="-1">3. Rekodi ya Maelezo ya Makabila Makuu <a class="header-anchor" href="#_3-rekodi-ya-maelezo-ya-makabila-makuu" aria-label="Permalink to &quot;3. Rekodi ya Maelezo ya Makabila Makuu&quot;">​</a></h2><h3 id="_3-1-aina-ya-umbo-la-mtu" tabindex="-1">3.1 Aina ya umbo la mtu <a class="header-anchor" href="#_3-1-aina-ya-umbo-la-mtu" aria-label="Permalink to &quot;3.1 Aina ya umbo la mtu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la mtu</td><td>Uwezo wa kuzingatia ni imara sana, uwezo wa kujifunza ni maarufu, uwezo wa kuzaliana ni wastani, umri wa wastani ni miaka 80-120</td><td>Utofauti wa kitamaduni ni juu sana, mtaalamu wa shirikisho la kijamii na ujenzi wa taasisi</td><td>Moja ya makabila ya msingi ya utamaduni wa usawa, idadi ya watu ni kubwa zaidi, inacheza jukumu la kuongoza katika uongozi na utamaduni</td></tr><tr><td>Kabila la fairy</td><td>Umri ni mrefu sana (wastani zaidi ya miaka 500), uhusiano wa karibu na nishati ya asili ni juu, sura ni nzuri</td><td>Inaheshimu asili na sanaa, utamaduni ni zuri na safi, mtaalamu wa uchawi na upigaji mishale</td><td>Ngome ya kitamaduni na sanaa ya utamaduni wa usawa, mchango maarufu katika ulinzi wa mazingira na urembo</td></tr><tr><td>Kabila la dwarf</td><td>Mwili ni mfupi lakini imara, uhusiano wa kuzaliwa na metali na madini ni karibu, umri ni takriban miaka 300</td><td>Inaheshimu ufundi na kuchora, utamaduni ni rahisi na imara, mtaalamu wa uhandisi na ujenzi</td><td>Ngome ya utengenezaji wa uhandisi wa utamaduni wa usawa, haiwezi kubadilishwa katika ujenzi wa miundombinu ya msingi na kuchora vifaa vya kimataifa</td></tr><tr><td>Kabila la giant</td><td>Mwili ni mkubwa sana (urefu wa wastani zaidi ya mita 5), nguvu ni imara sana, umri ni takriban miaka 200</td><td>Inaheshimu nguvu na heshima, utamaduni ni mkali na jasiri, mtaalamu wa kazi nzito na vita</td><td>Nguvu ya kazi nzito na ulinzi ya utamaduni wa usawa, inacheza jukumu muhimu katika miradi mikubwa na ulinzi wa usawa</td></tr><tr><td>Kabila la gnome</td><td>Mwili ni mfupi sana (urefu wa wastani chini ya mita 1), akili ni juu sana, talanta katika mitambo na uvumbuzi</td><td>Inaheshimu maarifa na ubunifu, utamaduni ni hai na furaha, mtaalamu wa uvumbuzi wa teknolojia</td><td>Nguvu ya ubunifu wa teknolojia ya utamaduni wa usawa, ina matokeo katika utafiti wa teknolojia na ubunifu</td></tr></tbody></table><h3 id="_3-2-aina-ya-umbo-la-mnyama" tabindex="-1">3.2 Aina ya umbo la mnyama <a class="header-anchor" href="#_3-2-aina-ya-umbo-la-mnyama" aria-label="Permalink to &quot;3.2 Aina ya umbo la mnyama&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la dragon</td><td>Umri ni mrefu sana (maelfu ya miaka), talanta ya nguvu na uchawi ni juu sana, inaweza kubadilisha kuwa umbo la mtu</td><td>Inaheshimu nguvu na hekima, utamaduni ni kiburi na kina, mtaalamu wa mkusanyiko wa mali na ulinzi wa maarifa</td><td>Nguvu ya vita ya kiwango cha juu na mlinzi wa maarifa wa utamaduni wa usawa, nafasi inayoheshimiwa katika ulinzi wa usawa na ulinzi wa vitabu vya kale</td></tr><tr><td>Kabila la phoenix</td><td>Ina uwezo wa kuzaliwa upya kwa nirvana, uhusiano wa karibu na kiwango cha moto ni juu sana, inaweza kubadilisha kuwa umbo la mtu</td><td>Inaheshimu kuzaliwa upya na tumaini, utamaduni ni mwangaza na moto, mtaalamu wa matibabu na usafi</td><td>Nguvu ya matibabu na usafi ya utamaduni wa usawa, inacheza jukumu la msingi katika uokoaji wa majanga makubwa na usafi wa nishati</td></tr><tr><td>Kabila la mtu-mbwa</td><td>Ina uwezo wa kubadilisha umbo, hisia ni za hali ya juu, uwezo wa kushirikiana katika kundi ni imara, umri ni takriban miaka 150</td><td>Inaheshimu kabila na uaminifu, utamaduni ni umoja na jasiri, mtaalamu ya uwindaji na ufuatiliaji</td><td>Nguvu ya usalama na ufuatiliaji ya utamaduni wa usawa, inacheza kiongozi katika kudumisha utaratibu na uchunguzi wa kati ya usawa</td></tr><tr><td>Kabila la paka-roho</td><td>Ina uwezo wa kubadilisha umbo, akili na uwezo wa kuvutia ni juu sana, umri ni takriban miaka 500</td><td>Inaheshimu hekima na mkakati, utamaduni ni hai na mjanja, mtaalamu wa ubalozi wa kigeni na habari</td><td>Nguvu ya ubalozi wa kigeni na habari ya utamaduni wa usawa, utendaji wa bora katika ubalozi wa kati ya usawa na ukusanyaji wa taarifa</td></tr><tr><td>Kabila la mtu-dubu</td><td>Mwili ni imara sana, uvumilivu ni wa kushangaza, tabia ya kulala msimu wa baridi, umri ni takriban miaka 200</td><td>Inaheshimu uimara na amani, utamaduni ni tulivu na mpenye, mtaalamu wa kazi ya mwili na ulinzi</td><td>Nguvu ya kazi na ulinzi ya utamaduni wa usawa, inakuwa na kuaminika na thabiti katika kuchimba rasilimali na kulinda vifaa vya muhimu</td></tr></tbody></table><h3 id="_3-3-aina-ya-umbo-la-mmea" tabindex="-1">3.3 Aina ya umbo la mmea <a class="header-anchor" href="#_3-3-aina-ya-umbo-la-mmea" aria-label="Permalink to &quot;3.3 Aina ya umbo la mmea&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la mti-roho</td><td>Umri ni mrefu sana (maelfu hadi makumi ya maelfu ya miaka), imeunganishwa kwa kina na asili, inaweza kuhamia polepole</td><td>Inaheshimu asili na wakati, utamaduni ni tulivu na kina, mtaalamu wa uchawi wa maisha na kudumisha mazingira</td><td>Mlinzi wa mazingira ya utamaduni wa usawa, inacheza jukumu lisiloweza kubadilishwa katika ulinzi wa mazingira na urejeshaji wa mazingira</td></tr><tr><td>Kabila la ua-roho</td><td>Mwili ni mdogo, uhusiano wa karibu na nishati ya maisha ni juu sana, ina uwezo wa kuponya, umri ni takriban miaka 300</td><td>Inaheshimu uzuri na maisha, utamaduni ni mpenye na mzuri, mtaalamu wa matibabu na bustani</td><td>Nguvu ya matibabu na bustani ya utamaduni wa usawa, mchango maarufu katika uhakika wa matibabu na kijani kijani mwa jiji</td></tr><tr><td>Kabila la mzizi</td><td>Mwili unaweza kunyoosha na kufunga kwa uhuru, uwezo wa kuzingatia ni imara sana, ina uwezo wa kuishi kwa mnyama na usawa</td><td>Inaheshimu muunganisho na usawa, utamaduni ni laini na kufichua, mtaalamu wa kujenga mtandao na kuhamisha rasilimali</td><td>Nguvu ya kujenga mtandao ya utamaduni wa usawa, inaonyesha talanta maalum katika kujenga mtandao wa nishati na mtandao wa taarifa</td></tr></tbody></table><h3 id="_3-4-aina-ya-umbo-la-kiwango" tabindex="-1">3.4 Aina ya umbo la kiwango <a class="header-anchor" href="#_3-4-aina-ya-umbo-la-kiwango" aria-label="Permalink to &quot;3.4 Aina ya umbo la kiwango&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la kiwango cha moto</td><td>Ina kiwango cha moto kama mwili, joto ni juu sana, uwezo wa shambulio ni imara, umri ni takriban miaka 500</td><td>Inaheshimu shauku na nguvu, utamaduni ni kali na moja kwa moja, mtaalamu wa shambulio la nishati na kuchora</td><td>Nguvu ya uzalishaji wa nishati na kuchora ya utamaduni wa usawa, haiwezi kukosa katika uwasilishaji wa nishati na usindikaji wa joto la juu</td></tr><tr><td>Kabila la kiwango cha maji</td><td>Ina kiwango cha maji kama mwili, inaweza kubadilisha umbo kwa uhuru, uwezo wa kuponya ni imara, umri ni takriban miaka 500</td><td>Inaheshimu upole na kuzingatia, utamaduni ni joto na kufichua, mtaalamu wa matibabu na usafi</td><td>Nguvu ya usafi na usafiri wa utamaduni wa usawa, inacheza jukumu la msingi katika usimamizi wa rasilimali za maji na usafi wa vichafuzi</td></tr><tr><td>Kabila la kiwango cha upepo</td><td>Ina kiwango cha upepo kama mwili, kasi ni haraka sana, inaweza kuruka kwa uhuru, umri ni takriban miaka 500</td><td>Inaheshimu uhuru na kasi, utamaduni ni laini na wazi, mtaalamu wa mawasiliano na usafiri</td><td>Nguvu ya mawasiliano na usafiri wa utamaduni wa usawa, ufanisi ni juu sana katika uwasilishaji wa taarifa na usafiri wa haraka</td></tr><tr><td>Kabila la kiwango cha ardhi</td><td>Ina kiwango cha ardhi kama mwili, uwezo wa ulinzi ni imara sana, inaweza kuungana na ardhi, umri ni takriban miaka 800</td><td>Inaheshimu utulivu na uimara, utamaduni ni imara na inakuwa na kuaminika, mtaalamu wa ujenzi na ulinzi</td><td>Nguvu ya ujenzi na ulinzi ya utamaduni wa usawa, imara kama mwamba katika ujenzi wa miundombinu ya msingi na ulinzi wa usawa</td></tr></tbody></table><h3 id="_3-5-aina-ya-umbo-la-nishati" tabindex="-1">3.5 Aina ya umbo la nishati <a class="header-anchor" href="#_3-5-aina-ya-umbo-la-nishati" aria-label="Permalink to &quot;3.5 Aina ya umbo la nishati&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la mwangaza-roho</td><td>Ina nishati ya mwangaza safi kama umbo wa kuwepo, uwezo wa usafi ni imara sana, inaweza kupitia nafasi kwa uhuru</td><td>Inaheshimu mwangaza na usafi, utamaduni ni takatifu na juu, mtaalamu wa usafi na mwangaza</td><td>Nguvu ya usafi na uwasilishaji wa nishati ya utamaduni wa usawa, nafasi muhimu katika kutibu uchafuzi wa sheria na uwasilishaji wa nishati safi</td></tr><tr><td>Kabila la nishati ya giza</td><td>Ina nishati ya giza kama umbo wa kuwepo, inaweza kujificha katika utupu, uwezo wa kugundua ni imara sana</td><td>Inaheshimu ujasiri na hekima, utamaduni ni siri na kina, mtaalamu wa uchunguzi na ujasiri</td><td>Nguvu ya uchunguzi na usalama ya utamaduni wa usawa, utendaji wa bora katika ufuatiliaji wa usalama na majukumu ya siri</td></tr><tr><td>Kabila la radi</td><td>Ina nishati ya radi kama mwili, kasi na uwezo wa shambulio ni imara sana, inaweza kuhamia kwa kuwa umeme</td><td>Inaheshimu kasi na nguvu, utamaduni ni kali na moja kwa moja, mtaalamu wa shambulio la nishati na mwitikio wa haraka</td><td>Nguvu ya mwitikio wa haraka ya utamaduni wa usawa, haiwezi kubadilishwa katika uokoaji wa dharura na vita vya kasi ya juu</td></tr></tbody></table><h3 id="_3-6-aina-ya-umbo-la-ufahamu" tabindex="-1">3.6 Aina ya umbo la ufahamu <a class="header-anchor" href="#_3-6-aina-ya-umbo-la-ufahamu" aria-label="Permalink to &quot;3.6 Aina ya umbo la ufahamu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la kitu cha ufahamu</td><td>Ina ufahamu safi kama umbo wa kuwepo, haitegemei mchango wa mwili, inaweza kuingia na kutoka katika eneo la ufahamu kwa uhuru</td><td>Inaheshimu mawazo na hekima, utamaduni ni abstract na kina, mtaalamu wa mawasiliano ya ufahamu na usindikaji wa maarifa</td><td>Nguvu ya usindikaji wa maarifa na utafiti wa ufahamu wa utamaduni wa usawa, inaongoza mwelekeo katika usindikaji wa taarifa za ukubwa mkubwa na sayansi ya ufahamu</td></tr><tr><td>Kabila la ufahamu wa pamoja</td><td>Kitu cha ufahamu wa pamoja kinachoundwa kwa kuunganishwa kwa ufahamu wa kibinafsi wa idadi kubwa, hekima na uwezo hukua pamoja na kiwango</td><td>Inaheshimu pamoja na umoja, utamaduni ni kushirikiana na ufanisi, mtaalamu wa kushirikiana na hesabu za ukubwa mkubwa</td><td>Nguvu ya supercomputing na uamuzi wa pamoja wa utamaduni wa usawa, inacheza jukumu la msingi katika makosa ya ukubwa wa ultra-kubwa na uamuzi wa makubaliano</td></tr></tbody></table><h3 id="_3-7-aina-ya-umbo-la-mitambo" tabindex="-1">3.7 Aina ya umbo la mitambo <a class="header-anchor" href="#_3-7-aina-ya-umbo-la-mitambo" aria-label="Permalink to &quot;3.7 Aina ya umbo la mitambo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la mitambo</td><td>Ina muundo wa mitambo kama mwili, ina ufahamu wa kujitegemea, inaweza kuboresha na kurekebisha mwili kwa uhuru</td><td>Inaheshimu ufanisi na mantiki, utamaduni ni kimantiki na sahihi, mtaalamu wa utengenezaji na hesabu</td><td>Nguvu ya utengenezaji na hesabu ya utamaduni wa usawa, ufanisi ni juu sana katika uzalishaji wa viwanda na eneo la supercomputing</td></tr><tr><td>Kabila la uhai wa kidijitali</td><td>Ina taarifa za kidijitali kama umbo wa kuwepo, inaishi katika mtandao na nafasi ya kidijitali, inaweza kunakili na kuhamia kwa uhuru</td><td>Inaheshimu taarifa na ubunifu, utamaduni ni virtual na anuwai, mtaalamu wa ukuzaji wa programu na usindikaji wa data</td><td>Nguvu ya teknolojia ya kidijitali ya utamaduni wa usawa, inaongoza mwelekeo katika ukuzaji wa programu, uchambuzi wa data, na ujenzi wa mtandao</td></tr></tbody></table><h3 id="_3-8-aina-ya-umbo-la-mchanganyiko" tabindex="-1">3.8 Aina ya umbo la mchanganyiko <a class="header-anchor" href="#_3-8-aina-ya-umbo-la-mchanganyiko" aria-label="Permalink to &quot;3.8 Aina ya umbo la mchanganyiko&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jina la kabila</th><th>Tabia za msingi</th><th>Tabia za kitamaduni</th><th>Nafasi katika utamaduni wa usawa</th></tr></thead><tbody><tr><td>Kabila la nusu-mitambo</td><td>Umbo la mchanganyiko wa kabila la mtu na kabila la mitambo, sehemu ya mwili ni muundo wa mitambo, ina faida za kibiolojia na za mitambo</td><td>Inaheshimu kuunganishwa na maendeleo, utamaduni ni wazi na ubunifu, mtaalamu wa kushirikiana mtu-mashine na kuunganisha teknolojia</td><td>Miongozi wa kuunganisha teknolojia ya utamaduni wa usawa, inaendelea kupata mapambano katika eneo la kibiolojia-mitambo</td></tr><tr><td>Kabila la kiwango-mnyama</td><td>Umbo la mchanganyiko wa kabila la kiwango na kabila la mnyama, ina uwezo wa kudhibiti kiwango na tabia za mwili za mnyama</td><td>Inaheshimu asili na nguvu, utamaduni ni mwituni na siri, mtaalamu wa vita vya kiwango na kuishi mwituni</td><td>Nguvu ya uchunguzi wa mwituni na vita vya kiwango ya utamaduni wa usawa, utendaji maarufu katika uchunguzi wa usawa usiojulikana</td></tr></tbody></table><h2 id="_4-ulinzi-wa-haki-za-kabila" tabindex="-1">4. Ulinzi wa Haki za Kabila <a class="header-anchor" href="#_4-ulinzi-wa-haki-za-kabila" aria-label="Permalink to &quot;4. Ulinzi wa Haki za Kabila&quot;">​</a></h2><p>Chini ya mfumo wa Jamhuri ya Kabila Zote, kabila zote zenye akili zinafurahia haki za kisheria za sawa, hatua za mahsusi za ulinzi zinajumuisha:</p><ol><li><strong>Usawa wa haki za kisiasa</strong>: Kila kabila kina viti cha uwakilishi vilivyogawanywa kulingana na uwiano wa watu katika Baraza la Nanga, na makabila yenye watu wachache yana angalau kiti kimoja kilicholindwa.</li><li><strong>Ulinzi wa haki za kitamaduni</strong>: Kila kabila kina haki ya kudumisha na kukuza lugha, maandishi, dini, mila, na desturi za kitamaduni zake mwenyewe, na utamaduni wa usawa unaanzisha fedha maalum ya kulinda utamaduni wa makabila yanayotishiwa kutoweka.</li><li><strong>Usawa wa haki za elimu</strong>: Wanachama wa kila kabila wanafurahia haki ya sawa ya elimu, na mfumo wa elimu unazingatia kikamilifu tabia za kibaolojia na za utambuzi za makabila tofauti, hutoa mipango ya elimu tofauti.</li><li><strong>Usawa wa haki za u cultivating</strong>: Mfumo wa u cultivating wa asili wa mia tatu umefunguliwa kwa sawa kwa kabila zote, na mgawanyo wa rasilimali za u cultivating unazingatia kikamilifu tofauti za mwili na mahitaji ya nishati ya makabila tofauti.</li><li><strong>Ulinzi wa mahitaji maalum</strong>: Kwa makabila yenye mahitaji ya kibaolojia maalum (kama mahitaji ya mazingira ya nishati ya kabila la kiwango, mahitaji ya mwangaza wa kabila la mmea), utamaduni wa usawa hutoa ulinzi wa lengo katika vifaa vya umma na mazingira ya makazi.</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Orodha ya Kabila Zote ni uwasilishaji wa mahsusi wa dhana ya &quot;maendeleo ya pamoja ya kabila zote&quot; ya Ustaarabu wa Usawa wa Nanga. Kutoka umbo la mtu hadi umbo la ufahamu, kutoka uhai wa mwili hadi uhai wa kidijitali, kila kabila kinachangia nguvu isiyoweza kubadilishwa kwa utamaduni wa usawa kwa njia yake ya kipekee ya kuwepo. Jamhuri ya Kabila Zote haimaanishi kuunganisha kabila zote kuwa kabila la mtu, bali kufikia mageuzi ya pamoja kwa msingi wa kutoa heshima kwa anuwai—hii ndiyo sababu ya msingi ya kwanini utamaduni wa usawa unazidi ustaarabu wa kuitoaji.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>50-Muhtasari wa Usoo wa Kabila Zote</li><li>51-Nafasi na Tabia za Kabila la Mtu</li><li>77-Uanzishaji wa Jamhuri ya Kabila Zote</li></ul>',31)])])}const b=i(m,[["render",l]]);export{s as __pageData,b as default};
